-- The LinkedIn extension's read-task queue, its results, the per-workspace pacing gate and the hashed extension token (lib/linkedin-tasks/store.ts, #1122),
-- with the 0039 tenant-tombstone guards generated by the same pipeline as every tenant table.
CREATE TABLE li_ext_tokens (tenant_id TEXT PRIMARY KEY, token_hash TEXT NOT NULL, created_by TEXT NOT NULL, created_at BIGINT NOT NULL, last_used_at BIGINT);

CREATE TABLE li_results (task_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, kind TEXT NOT NULL, source_url TEXT NOT NULL, fetched_at BIGINT NOT NULL, payload TEXT NOT NULL);

CREATE TABLE li_task_gate (tenant_id TEXT PRIMARY KEY, tz TEXT, next_allowed_at BIGINT NOT NULL DEFAULT 0, paused BIGINT NOT NULL DEFAULT 0);

CREATE TABLE li_tasks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, kind TEXT NOT NULL, url TEXT NOT NULL, status TEXT NOT NULL,
      requested_by TEXT, attempts BIGINT NOT NULL DEFAULT 0, lease_until BIGINT, created_at BIGINT NOT NULL, served_at BIGINT, done_at BIGINT, outcome TEXT);

CREATE INDEX li_results_tenant ON li_results (tenant_id, fetched_at);

CREATE INDEX li_tasks_queue ON li_tasks (tenant_id, status, created_at);

CREATE INDEX li_tasks_served ON li_tasks (tenant_id, served_at);

CREATE OR REPLACE FUNCTION dazl_guard_tomb_li_ext_tokens() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext(NEW.tenant_id));
  IF (EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant deleted'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tomb_li_ext_tokens ON li_ext_tokens;
CREATE TRIGGER tomb_li_ext_tokens BEFORE INSERT ON li_ext_tokens FOR EACH ROW EXECUTE FUNCTION dazl_guard_tomb_li_ext_tokens();

